const RECIPE_PACK_BASE64="";
function recipeAmount(x){return x.amount==null?escapeXML(x.item):`${fmt(x.amount,6)} ${escapeXML(x.item)}`}
function recipeEquation(r){return `${r.inputs.map(recipeAmount).join(' ＋ ')||'自然采集'} → ${r.outputs.map(recipeAmount).join(' ＋ ')||'处理／消耗'}`}
function renderCatalog(){const q=$('recipeSearch').value.trim().toLowerCase();const all=RECIPE_PACKAGE.recipes,rs=all.filter(r=>JSON.stringify(r).toLowerCase().includes(q));$('recipeCount').textContent=`显示 ${rs.length} / ${all.length} 条配方。输入催化剂不随反应倍率折算，按启用设备单独供给。`;$('recipeCatalogTable').innerHTML=rowsTable(['原表行号','投入 → 产出（每次反应）','反应秒数','设备','环境','催化剂/min'],rs.map(r=>[r.sourceRow,recipeEquation(r),fmt(r.seconds),escapeXML(r.machine||'—'),escapeXML(r.environment||'—'),r.catalyst?`${escapeXML(r.catalyst)} ${fmt(r.catalystPerMinute,6)}`:'无']));}
const BALANCE_RECIPES=RECIPE_PACKAGE.recipes.filter(r=>r.outputs.some(o=>Number.isFinite(o.amount)&&o.amount>0)&&r.seconds>0);
$('balanceRecipe').innerHTML=BALANCE_RECIPES.map(r=>`<option value="${r.id}">${r.sourceRow} · ${r.outputs.map(o=>escapeXML(o.item)).join('、')} · ${escapeXML(r.machine)}</option>`).join('');
function selectBalanceRecipe(){const r=BALANCE_RECIPES.find(r=>r.id===$('balanceRecipe').value);$('balanceOutput').innerHTML=(r?.outputs||[]).map((o,i)=>o.amount>0?`<option value="${i}">${escapeXML(o.item)}</option>`:'').join('');renderSingleBalance()}
function renderSingleBalance(){const r=BALANCE_RECIPES.find(r=>r.id===$('balanceRecipe').value),o=r?.outputs[+$('balanceOutput').value],rate=+$('balanceRate').value;if(!r||!o)return;if(!Number.isFinite(rate)||rate<0||rate>1e6){$('balanceResult').textContent='请输入0至1000000的有效产率';return}const load=rate/(o.amount*60/r.seconds),machines=rate>1e-8?Math.ceil(load-1e-8):0,catalyst=(r.catalystPerMinute||0)*machines;const raw={};for(const x of r.inputs){if(!raw[x.item])raw[x.item]={reaction:0,activation:0};raw[x.item].reaction+=(x.amount||0)*60/r.seconds*load}if(r.catalyst){if(!raw[r.catalyst])raw[r.catalyst]={reaction:0,activation:0};raw[r.catalyst].activation+=catalyst}let solidEquivalent=(raw['息壤']?.reaction||0)+(raw['息壤']?.activation||0)+(raw['液化息壤']?.reaction||0)+(raw['液化息壤']?.activation||0);
$('balanceResult').innerHTML=`<p><strong>${escapeXML(o.item)} ${fmt(rate,6)}/min</strong>，等价满速 ${fmt(load,6)}，至少启用 ${machines} ${r.scope==='production-line'?'条等价产线':'台'} ${escapeXML(r.machine)}。${r.scope==='production-line'?'<strong>整线等价配平；环境占用与共享设备请以规划结果为准。</strong>':''}${r.environment?`所需环境：${escapeXML(r.environment)}。`:''}</p>`+rowsTable(['输入/min','反应消耗','固定催化剂／激活','总供给'],Object.entries(raw).map(([item,v])=>[escapeXML(item),fmt(v.reaction,6),fmt(v.activation,6),fmt(v.reaction+v.activation,6)]))+rowsTable(['输出／副产物','产率/min'],r.outputs.map(x=>[escapeXML(x.item),x.amount==null?'原表未给数量':fmt(x.amount*60/r.seconds*load,6)]))+`<p>息壤与液化息壤合计等价 ${fmt(solidEquivalent,6)} 息壤/min。这里展示整数启用设备的激活需求；多余产能由普通反应料控速。环境供给、前置加工、回收链及其他产线共享设备尚未合并。</p><p>查看上游：${r.inputs.map(x=>`<button class="outline upstream-recipe" data-item="${escapeXML(x.item)}">${escapeXML(x.item)}</button>`).join(' ')}</p>`;document.querySelectorAll('.upstream-recipe').forEach(b=>b.onclick=()=>{jumpUpstream(b.dataset.item)});}
$('recipeSearch').oninput=renderCatalog;$('balanceRecipe').onchange=selectBalanceRecipe;$('balanceOutput').onchange=renderSingleBalance;$('balanceRate').oninput=renderSingleBalance;
$('recipeJsonDownload').onclick=()=>saveBlob(new Blob([JSON.stringify(RECIPE_PACKAGE,null,2)],{type:'application/json;charset=utf-8'}),'终末地全配方_v10.json');
$('recipePackDownload').onclick=()=>{const bytes=Uint8Array.from(atob(RECIPE_PACK_BASE64),c=>c.charCodeAt(0));saveBlob(new Blob([bytes],{type:'application/zip'}),'终末地配方资源包_v10.zip')};
$('balanceRecipe').value=BALANCE_RECIPES.find(r=>r.outputs.some(o=>o.item==='中容武陵电池'))?.id||BALANCE_RECIPES[0].id;renderCatalog();selectBalanceRecipe();

function jumpUpstream(item){const candidates=BALANCE_RECIPES.filter(r=>r.outputs.some(o=>o.item===item&&o.amount>0));$('recipeSearch').value=item;renderCatalog();if(candidates.length){$('balanceRecipe').value=candidates[0].id;selectBalanceRecipe();const index=candidates[0].outputs.findIndex(o=>o.item===item);$('balanceOutput').value=String(index);renderSingleBalance();$('recipeCount').textContent+=` 已跳转到${item}生产配方，共${candidates.length}种生产方式，可在配方下拉框切换。`;const target=$('balanceRecipe');if(target.scrollIntoView)target.scrollIntoView({behavior:'smooth',block:'center'});if(target.focus)target.focus({preventScroll:true})}else{$('recipeCount').textContent+=` 原表中没有${item}的生产配方，已展示相关词条。`;if($('recipeCount').scrollIntoView)$('recipeCount').scrollIntoView({behavior:'smooth',block:'center'})}}
